# C++ Qt5 Application to Convert Excel Files to CSV

Here's a complete C++ application using Qt5 that:
1. Creates a simple GUI with a button to select a directory
2. Scans the selected directory for Excel files (.xlsx, .xls)
3. Converts each Excel file to CSV
4. Saves the CSV files in a new "CSV_Output" subdirectory

```cpp
#include <QApplication>
#include <QMainWindow>
#include <QPushButton>
#include <QFileDialog>
#include <QVBoxLayout>
#include <QLabel>
#include <QMessageBox>
#include <QDir>
#include <QAxObject>
#include <QProgressBar>
#include <QFuture>
#include <QtConcurrent/QtConcurrent>

class ExcelToCsvConverter : public QMainWindow {
    Q_OBJECT

public:
    ExcelToCsvConverter(QWidget *parent = nullptr) : QMainWindow(parent) {
        setupUI();
    }

private slots:
    void selectDirectory() {
        QString dir = QFileDialog::getExistingDirectory(this, "Select Directory with Excel Files");
        if (!dir.isEmpty()) {
            directoryLabel->setText("Selected: " + dir);
            convertButton->setEnabled(true);
            selectedDirectory = dir;
        }
    }

    void convertFiles() {
        if (selectedDirectory.isEmpty()) {
            QMessageBox::warning(this, "No Directory", "Please select a directory first.");
            return;
        }

        // Create output directory
        QDir dir(selectedDirectory);
        QString outputDir = dir.filePath("CSV_Output");
        if (!dir.mkpath(outputDir)) {
            QMessageBox::critical(this, "Error", "Could not create output directory.");
            return;
        }

        // Find all Excel files
        QStringList excelFiles;
        QStringList filters;
        filters << "*.xlsx" << "*.xls" << "*.xlsm" << "*.xlsb";
        QDir dirFiles(selectedDirectory);
        excelFiles = dirFiles.entryList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "No Files", "No Excel files found in the selected directory.");
            return;
        }

        // Show progress
        progressBar->setRange(0, excelFiles.size());
        progressBar->setValue(0);
        statusLabel->setText("Converting files...");

        // Disable UI during conversion
        selectButton->setEnabled(false);
        convertButton->setEnabled(false);

        // Convert files
        bool allSuccess = true;
        for (const QString &file : excelFiles) {
            QString fullPath = dirFiles.filePath(file);
            QString csvPath = QDir(outputDir).filePath(file + ".csv");

            if (!convertExcelToCsv(fullPath, csvPath)) {
                allSuccess = false;
                statusLabel->setText("Failed to convert: " + file);
            }

            progressBar->setValue(progressBar->value() + 1);
            qApp->processEvents(); // Update UI
        }

        // Re-enable UI
        selectButton->setEnabled(true);
        convertButton->setEnabled(true);

        if (allSuccess) {
            statusLabel->setText("Conversion complete!");
            QMessageBox::information(this, "Success",
                QString("Converted %1 files to CSV.\nOutput directory: %2")
                .arg(excelFiles.size())
                .arg(outputDir));
        } else {
            statusLabel->setText("Conversion finished with errors");
        }
    }

private:
    bool convertExcelToCsv(const QString &excelPath, const QString &csvPath) {
        try {
            QAxObject excel("Excel.Application");
            QAxObject *workbooks = excel.querySubObject("Workbooks");
            QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelPath);

            if (!workbook) {
                return false;
            }

            // Save as CSV
            QAxObject *worksheets = workbook->querySubObject("Worksheets");
            QAxObject *worksheet = worksheets->querySubObject("Item(int)", 1);

            if (!worksheet) {
                workbook->dynamicCall("Close(bool)", false);
                excel.dynamicCall("Quit()");
                return false;
            }

            // Save as CSV (6 is xlCSV format)
            workbook->dynamicCall("SaveAs(const QString&, int, const QString&, const QString&, bool, bool)",
                                 csvPath, 6, "", "", false, false);

            workbook->dynamicCall("Close(bool)", false);
            excel.dynamicCall("Quit()");

            return true;
        } catch (...) {
            return false;
        }
    }

    void setupUI() {
        QWidget *centralWidget = new QWidget(this);
        QVBoxLayout *layout = new QVBoxLayout(centralWidget);

        directoryLabel = new QLabel("No directory selected", this);
        selectButton = new QPushButton("Select Directory", this);
        convertButton = new QPushButton("Convert to CSV", this);
        progressBar = new QProgressBar(this);
        statusLabel = new QLabel(this);

        progressBar->setVisible(false);
        convertButton->setEnabled(false);

        layout->addWidget(directoryLabel);
        layout->addWidget(selectButton);
        layout->addWidget(convertButton);
        layout->addWidget(progressBar);
        layout->addWidget(statusLabel);

        connect(selectButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);
        connect(convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::convertFiles);

        setCentralWidget(centralWidget);
        setWindowTitle("Excel to CSV Converter");
        resize(400, 200);
    }

    QLabel *directoryLabel;
    QPushButton *selectButton;
    QPushButton *convertButton;
    QProgressBar *progressBar;
    QLabel *statusLabel;
    QString selectedDirectory;
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    // Initialize COM for Excel automation
    CoInitializeEx(NULL, COINIT_MULTITHREADED);

    ExcelToCsvConverter converter;
    converter.show();

    int result = app.exec();

    // Uninitialize COM
    CoUninitialize();

    return result;
}

#include "main.moc"
```

## Requirements

1. **Qt5** - You'll need Qt5 installed with the following modules:
   - Qt Core
   - Qt GUI
   - Qt Widgets
   - ActiveQt (for Excel automation)

2. **Microsoft Excel** - This application uses Excel's COM interface, so Microsoft Excel must be installed on the system.

## How to Build

1. Create a project file (e.g., `ExcelToCsv.pro`):
```
QT += core gui widgets axcontainer
SOURCES += main.cpp
TARGET = ExcelToCsv
```

2. Build with:
```
qmake ExcelToCsv.pro
make
```

## Notes

- The application uses QAxObject to interface with Excel via COM. This requires Microsoft Excel to be installed.
- For large files or many files, the conversion might take some time.
- The application creates a "CSV_Output" subdirectory in the selected directory to store the converted files.
- Each Excel file is converted to a CSV file with the same name but with a .csv extension.
- The first worksheet in each Excel file is converted to CSV.

## Alternative Approach

If you don't want to depend on Excel being installed, you could use a library like:
- [libxlsxwriter](https://github.com/jmcnamara/libxlsxwriter) (write only)
- [QXlsx](https://github.com/dbobrenko/QXlsx) (read/write)

But these would require additional dependencies and might not handle all Excel features perfectly.

